      float d = length(uv);
      float pi = 3.141592653589793;
      float p = amzp_points;
      float seg = (2.0*pi/p);
      float k = cos(floor(0.5 + a/seg)*seg - a) * amzp_inner + 1.0;
      return d - r * k;
