      float2 iResolution = screen.zw;

      float2 uv = (fragCoord - 0.5*iResolution.xy) / max(iResolution.y, 1.0);


      float star = starShape(uv, amzp_starRadius, float(amzp_points), amzp_inner);
      float distort = 0.0;
      distort += plasmaLayer(uv, amzp_scale1, amzp_speed1, 0.0);
      distort += plasmaLayer(uv, amzp_scale2, amzp_speed2, 2.0);
      distort += plasmaLayer(uv, amzp_scale3, amzp_speed3, 5.0);


      float2 pixelSize = float2(1.0) / max(iResolution, float2(1.0));
      float4 blurMid = amzTexture(1, amzScreenNorm());
      float4 blurUp = amzTexture(1, amzScreenNorm() + pixelSize*float2(0.0,-4.0));
      float4 blurLeft = amzTexture(1, amzScreenNorm() + pixelSize*float2(-4.0,0.0));
      float dx = blurMid.a - blurLeft.a;
      float dy = blurMid.a - blurUp.a;
      float2 gradN = normalize(float2(dx, dy));
      float p = blurMid.a;

      float prog = clamp(amzp_burnProgress + ((amzp_autoAnimate>0.5) ? time * amzp_burnRate : 0.0), 0.0, 1.0);

      float dist = mix(0.95, 0.05, prog);

      dist += (0.5 - (amzp_distance * 0.4 + 0.5)) * 0.1;
      float ringW = max(amzp_burnWidth, 0.001);

      float n = vnoise2(amzScreenNorm()*amzp_edgeNoiseScale + float2(amzp_seed*7.123, amzp_seed*3.71 + time*0.05));
      float distN = dist + (amzp_edgeNoiseAmt * (n - 0.5)) * ringW * 1.5;

      float ringWFeather = ringW * mix(0.5, 2.0, clamp(amzp_smoothFeather,0.0,1.0));
      float core = 1.0 - smoothstep(0.0, ringWFeather, abs(p - distN));
      float hardnessExp = mix(6.0, 1.0, clamp(amzp_burnHardness,0.0,1.0));
      float ringMask = pow(saturate(core), hardnessExp);

      if(int(amzp_edgeSide)==0){ 
        ringMask *= (1.0 - step(distN, p));
      } else if(int(amzp_edgeSide)==1){ 
        ringMask *= step(distN, p);
      }


      float heatN = (vnoise2(amzScreenNorm()*amzp_heatScale + float2(amzp_seed*1.23, 17.31 + time*0.2)) - 0.5);

      float2 heatDir = normalize(gradN + float2(1e-6));
      float2 sampleUV = amzScreenNorm() + heatDir * amzp_heatStrength * ringMask * (0.5 + heatN);


      float4 texColor = amzTexture(0, sampleUV);


      float edgeProx = saturate(1.0 - abs(p - distN) / ringW);
      float3 fireCol = firePalette(edgeProx);
      float3 rainbowCol = palette(star*6.0);
      float3 emissive = (int(amzp_paletteMode)==0 ? fireCol : rainbowCol);

      emissive = mix(emissive, float3(1.0), clamp(amzp_whiteHot,0.0,2.0) * pow(edgeProx, 2.0));

      emissive *= amzp_tintColor.rgb;

      float dNorm = abs(p - distN) / max(ringW, 1e-4);
      float glowArg = pow(dNorm, clamp(amzp_glowFeather,0.5,3.0));
      float3 glow = emissive * amzp_glowIntensity * exp(-amzp_glowFalloff * glowArg);

      float blobN = vnoise2(amzScreenNorm()*(amzp_edgeNoiseScale*0.7) + float2(amzp_seed*2.17, time*0.12));
      float hot = saturate((edgeProx + (blobN-0.5)*0.6 - amzp_hotspotThresh) * (2.0 + amzp_hotspotGain));
      glow *= (1.0 + pow(hot, amzp_hotspotGain) * 1.5);

      float auraDist = abs(p - (distN + ringW*1.15)) / max(ringW*2.2, 1e-4);
      float3 aura = emissive * amzp_auraIntensity * exp(-amzp_auraFalloff * auraDist);
      float3 finalColor = glow + aura;


      float edgeMask = ringMask;


      float4 masked = float4(finalColor, 1.0) * edgeMask;


      if((amzp_hideBase>0.5)){
        amzOutput = masked;
        return;
      }


      float cutWidth = ringW * (1.0 + clamp(amzp_cutFeather,0.0,1.0)*1.5);
      float cutMask = smoothstep(distN, distN + cutWidth, p) * edgeMask;
      texColor.a *= (1.0 - cutMask * amzp_cutAmount);


      float4 outColor;
      if(int(amzp_blendMode)==1){
        outColor = float4((texColor.rgb/texColor.a) * masked.rgb, 1.0) * texColor.a;
      } else if(int(amzp_blendMode)==2){
        outColor = float4(1.0 - (1.0 - (texColor.rgb/texColor.a)) * (1.0 - masked.rgb), 1.0) * texColor.a;
      } else {
        outColor = masked * texColor.a;
        outColor = texColor*(1.0 - outColor.a) + outColor;
      }


      amzOutput = mix(texColor * amzp_fill, outColor, amzp_alpha);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

